-- SQLite WAL database: durable numbering, revocation and recoverable records.
CREATE TABLE request_context (id INTEGER PRIMARY KEY CHECK(id=1),actor_id INTEGER,role TEXT,assigned_only TEXT NOT NULL DEFAULT 'false');
INSERT INTO request_context(id) VALUES (1);
CREATE TABLE reference_counters (prefix TEXT NOT NULL, year INTEGER NOT NULL, value INTEGER NOT NULL, PRIMARY KEY(prefix,year));
INSERT INTO reference_counters SELECT 'L',CAST(substr(lead_number,3,4) AS INTEGER),max(CAST(substr(lead_number,8) AS INTEGER)) FROM leads GROUP BY 2;
INSERT INTO reference_counters SELECT 'ECC',CAST(substr(client_number,5,4) AS INTEGER),max(CAST(substr(client_number,10) AS INTEGER)) FROM clients GROUP BY 2;
CREATE UNIQUE INDEX users_email_normalized ON users(lower(email));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE account_tokens (token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE TABLE mail_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),sent_at TEXT,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,claim_token TEXT,claimed_until TEXT);
ALTER TABLE leads ADD COLUMN deleted_at TEXT;
ALTER TABLE leads ADD COLUMN converted_client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL;
ALTER TABLE clients ADD COLUMN deleted_at TEXT;
-- Rebuild tasks to permit client-only tasks in existing SQLite databases.
CREATE TABLE tasks_v2 (
 id INTEGER PRIMARY KEY AUTOINCREMENT,lead_id INTEGER REFERENCES leads(id) ON DELETE CASCADE,
 client_id INTEGER REFERENCES clients(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 255),
 description TEXT,due_date TEXT,priority TEXT NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High','Urgent')),
 status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','In Progress','Done')),
 assigned_to_id INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')),
 CHECK(lead_id IS NOT NULL OR client_id IS NOT NULL));
INSERT INTO tasks_v2(id,lead_id,title,description,due_date,priority,status,assigned_to_id,created_at) SELECT id,lead_id,title,description,due_date,priority,status,assigned_to_id,created_at FROM tasks;
DROP TABLE tasks;
ALTER TABLE tasks_v2 RENAME TO tasks;
CREATE INDEX idx_tasks_lead ON tasks(lead_id);
CREATE INDEX idx_tasks_client ON tasks(client_id);
CREATE INDEX idx_tasks_status ON tasks(status);
CREATE INDEX idx_tasks_due ON tasks(due_date);
CREATE TABLE reminder_receipts (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,due_date TEXT NOT NULL,read_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(user_id,task_id,due_date));
CREATE TABLE followup_receipts (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,lead_id INTEGER NOT NULL REFERENCES leads(id) ON DELETE CASCADE,due_date TEXT NOT NULL,read_at TEXT NOT NULL DEFAULT (datetime('now')),PRIMARY KEY(user_id,lead_id,due_date));
CREATE TRIGGER revoke_sessions AFTER UPDATE OF password_hash,role ON users
WHEN NEW.password_hash IS NOT OLD.password_hash OR NEW.role IS NOT OLD.role BEGIN
 DELETE FROM sessions WHERE user_id=NEW.id;
 DELETE FROM account_tokens WHERE user_id=NEW.id;
END;
CREATE TRIGGER audit_users_insert AFTER INSERT ON users BEGIN
 INSERT INTO audit_log(entity_type,entity_id,entity_name,action,changes,actor_id) VALUES ('user',NEW.id,NEW.name,'created',(SELECT json_group_object(key,json(value)) FROM json_each(json_object('id',json_object('from',NULL,'to',NEW.id),'email',json_object('from',NULL,'to',NEW.email),'name',json_object('from',NULL,'to',NEW.name),'role',json_object('from',NULL,'to',NEW.role),'created_at',json_object('from',NULL,'to',NEW.created_at))) WHERE json_extract(value,'$.from') IS NOT json_extract(value,'$.to')),(SELECT actor_id FROM request_context WHERE id=1));
END;
CREATE TRIGGER audit_users_update AFTER UPDATE ON users BEGIN
 INSERT INTO audit_log(entity_type,entity_id,entity_name,action,changes,actor_id) VALUES ('user',NEW.id,NEW.name,'updated',(SELECT json_group_object(key,json(value)) FROM json_each(json_object('id',json_object('from',OLD.id,'to',NEW.id),'email',json_object('from',OLD.email,'to',NEW.email),'name',json_object('from',OLD.name,'to',NEW.name),'role',json_object('from',OLD.role,'to',NEW.role),'created_at',json_object('from',OLD.created_at,'to',NEW.created_at))) WHERE json_extract(value,'$.from') IS NOT json_extract(value,'$.to')),(SELECT actor_id FROM request_context WHERE id=1));
END;
