CREATE TRIGGER validate_leads_full_name_insert BEFORE INSERT ON leads WHEN length(trim(NEW.full_name)) NOT BETWEEN 1 AND 200 BEGIN SELECT RAISE(ABORT,'Invalid full_name'); END;
CREATE TRIGGER validate_leads_full_name_update BEFORE UPDATE ON leads WHEN length(trim(NEW.full_name)) NOT BETWEEN 1 AND 200 BEGIN SELECT RAISE(ABORT,'Invalid full_name'); END;
CREATE TRIGGER validate_clients_full_name_insert BEFORE INSERT ON clients WHEN length(trim(NEW.full_name)) NOT BETWEEN 1 AND 200 BEGIN SELECT RAISE(ABORT,'Invalid full_name'); END;
CREATE TRIGGER validate_clients_full_name_update BEFORE UPDATE ON clients WHEN length(trim(NEW.full_name)) NOT BETWEEN 1 AND 200 BEGIN SELECT RAISE(ABORT,'Invalid full_name'); END;
CREATE TRIGGER validate_leads_stage_insert BEFORE INSERT ON leads WHEN NEW.stage NOT IN ('New Lead','Contacted','Initial Assessment','Qualified','Consultation Booked','Proposal Sent','Converted','Closed/Lost') BEGIN SELECT RAISE(ABORT,'Invalid stage'); END;
CREATE TRIGGER validate_leads_stage_update BEFORE UPDATE ON leads WHEN NEW.stage NOT IN ('New Lead','Contacted','Initial Assessment','Qualified','Consultation Booked','Proposal Sent','Converted','Closed/Lost') BEGIN SELECT RAISE(ABORT,'Invalid stage'); END;
